from __future__ import annotations

"""Models for OpenAI Batch API input requests and output results.

A batch input is JSONL, one request per line, each tagged with a ``custom_id``
you choose. The output is also JSONL, but two things bite naive code: the output
lines are **not** guaranteed to be in input order, and some lines are failures
(``response`` null with an ``error``, or a non-200 ``response.status_code``).
The ``custom_id`` is the only reliable way to tie a result back to its request.
"""

from dataclasses import dataclass, field


@dataclass(frozen=True)
class BatchRequestLine:
    custom_id: str
    body: dict
    method: str = "POST"
    url: str = "/v1/chat/completions"

    def __post_init__(self) -> None:
        if not self.custom_id.strip():
            raise ValueError("custom_id is required")

    def to_jsonl_obj(self) -> dict:
        return {
            "custom_id": self.custom_id,
            "method": self.method,
            "url": self.url,
            "body": self.body,
        }


@dataclass(frozen=True)
class BatchResultLine:
    custom_id: str
    status_code: int | None = None
    body: dict | None = None
    error: dict | None = None

    def __post_init__(self) -> None:
        if not self.custom_id.strip():
            raise ValueError("result custom_id is required")

    @classmethod
    def from_obj(cls, obj: dict) -> "BatchResultLine":
        custom_id = str(obj.get("custom_id", "")).strip()
        response = obj.get("response")
        status_code = None
        body = None
        if isinstance(response, dict):
            status_code = response.get("status_code")
            body = response.get("body")
        return cls(
            custom_id=custom_id,
            status_code=status_code,
            body=body,
            error=obj.get("error"),
        )

    def is_success(self) -> bool:
        return self.error is None and self.status_code == 200

    def failure_reason(self) -> str | None:
        if self.is_success():
            return None
        if self.error is not None:
            return str(self.error.get("code") or self.error.get("message") or "error")
        if self.status_code is not None and self.status_code != 200:
            return f"http_{self.status_code}"
        return "unknown_error"


def build_chat_request(custom_id: str, model: str, prompt: str) -> BatchRequestLine:
    body = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
    }
    return BatchRequestLine(custom_id=custom_id, body=body)


def request_custom_ids(requests: list[BatchRequestLine]) -> list[str]:
    return [r.custom_id for r in requests]


def result_custom_ids(results: list[BatchResultLine]) -> list[str]:
    return [r.custom_id for r in results]

