from __future__ import annotations

"""Decode a Batch API output file (JSONL) into result lines.

Each non-blank line is one JSON object. Blank lines are ignored. A line that is
not valid JSON is collected as a parse error rather than silently dropped, so a
corrupt output file is visible instead of shrinking the result set.
"""

import json
from dataclasses import dataclass, field

from batch_models import BatchResultLine


@dataclass
class ParsedOutput:
    results: list[BatchResultLine] = field(default_factory=list)
    parse_errors: list[str] = field(default_factory=list)

    def result_count(self) -> int:
        return len(self.results)

    def custom_ids(self) -> list[str]:
        return [r.custom_id for r in self.results]


def parse_output_jsonl(text: str) -> ParsedOutput:
    parsed = ParsedOutput()
    for line_number, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError as exc:
            parsed.parse_errors.append(f"line {line_number}: {exc.msg}")
            continue
        parsed.results.append(BatchResultLine.from_obj(obj))
    return parsed


def parse_result_objects(objs: list[dict]) -> list[BatchResultLine]:
    """Decode already-loaded JSON objects (e.g. from a test fixture)."""

    return [BatchResultLine.from_obj(obj) for obj in objs]


def to_output_jsonl(results: list[dict]) -> str:
    """Serialize raw result objects back to JSONL (used for round-tripping)."""

    return "\n".join(json.dumps(obj) for obj in results)


def success_results(results: list[BatchResultLine]) -> list[BatchResultLine]:
    return [r for r in results if r.is_success()]


def failed_results(results: list[BatchResultLine]) -> list[BatchResultLine]:
    return [r for r in results if not r.is_success()]


def partition_results(
    results: list[BatchResultLine],
) -> tuple[list[BatchResultLine], list[BatchResultLine]]:
    """Split into (succeeded, failed) while keeping original order."""

    succeeded: list[BatchResultLine] = []
    failed: list[BatchResultLine] = []
    for result in results:
        (succeeded if result.is_success() else failed).append(result)
    return succeeded, failed


def count_by_outcome(results: list[BatchResultLine]) -> dict[str, int]:
    succeeded, failed = partition_results(results)
    return {"total": len(results), "succeeded": len(succeeded), "failed": len(failed)}


def has_failures(results: list[BatchResultLine]) -> bool:
    return any(not r.is_success() for r in results)


def failure_reasons(results: list[BatchResultLine]) -> dict[str, str]:
    """Map each failed line's custom_id to its reason."""

    return {r.custom_id: (r.failure_reason() or "error") for r in failed_results(results)}

