from __future__ import annotations

"""Reconcile a batch's requests against its output file.

Given the requests we submitted and the raw output JSONL, produce a report the
job runner acts on: which custom_ids succeeded, which failed (and why), which
never came back, and any result lines we did not recognize.
"""

from dataclasses import dataclass, field

from batch_models import BatchRequestLine, BatchResultLine
from batch_output_parser import parse_output_jsonl
from result_matcher import match_results, unmatched_result_ids


@dataclass
class ReconciliationReport:
    matched: dict[str, BatchResultLine | None]
    succeeded: list[str] = field(default_factory=list)
    failed: list[tuple[str, str]] = field(default_factory=list)
    missing: list[str] = field(default_factory=list)
    extra: list[str] = field(default_factory=list)

    def content_for(self, custom_id: str):
        from content_extractor import extract_message_content

        result = self.matched.get(custom_id)
        return extract_message_content(result) if result else None

    def is_clean(self) -> bool:
        return not self.failed and not self.missing and not self.extra

    def failed_ids(self) -> list[str]:
        return [cid for cid, _ in self.failed]

    def success_rate(self) -> float:
        total = len(self.matched)
        if total == 0:
            return 0.0
        return len(self.succeeded) / total

    def as_dict(self) -> dict[str, object]:
        return {
            "succeeded": list(self.succeeded),
            "failed": list(self.failed),
            "missing": list(self.missing),
            "extra": list(self.extra),
        }

    def needs_retry(self) -> list[str]:
        """custom_ids worth resubmitting: failures plus anything missing."""

        return self.failed_ids() + list(self.missing)


def reconcile_results(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> ReconciliationReport:
    matched = match_results(requests, results)
    report = ReconciliationReport(matched=matched)

    for request in requests:
        result = matched.get(request.custom_id)
        if result is None:
            report.missing.append(request.custom_id)
        elif result.is_success():
            report.succeeded.append(request.custom_id)
        else:
            report.failed.append((request.custom_id, result.failure_reason() or "error"))

    report.extra = unmatched_result_ids(requests, results)
    return report


def reconcile_output_file(
    requests: list[BatchRequestLine],
    output_jsonl: str,
) -> ReconciliationReport:
    parsed = parse_output_jsonl(output_jsonl)
    return reconcile_results(requests, parsed.results)

