from __future__ import annotations

"""Pull the useful payload out of a successful batch result line.

A successful chat result nests the text under
``response.body.choices[0].message.content``. These helpers keep the digging in
one place so callers work with plain strings.
"""

from batch_models import BatchResultLine


def extract_message_content(result: BatchResultLine) -> str | None:
    if not result.is_success() or not result.body:
        return None
    choices = result.body.get("choices") or []
    if not choices:
        return None
    message = choices[0].get("message") or {}
    return message.get("content")


def extract_finish_reason(result: BatchResultLine) -> str | None:
    if not result.is_success() or not result.body:
        return None
    choices = result.body.get("choices") or []
    if not choices:
        return None
    return choices[0].get("finish_reason")


def extract_total_tokens(result: BatchResultLine) -> int:
    if not result.is_success() or not result.body:
        return 0
    usage = result.body.get("usage") or {}
    return int(usage.get("total_tokens", 0))


def extract_error_message(result: BatchResultLine) -> str | None:
    if result.is_success():
        return None
    if result.error is not None:
        return str(result.error.get("message") or result.error.get("code") or "error")
    if result.body and isinstance(result.body.get("error"), dict):
        return str(result.body["error"].get("message") or "error")
    return result.failure_reason()


def summarize_result(result: BatchResultLine) -> dict[str, object]:
    return {
        "custom_id": result.custom_id,
        "ok": result.is_success(),
        "content": extract_message_content(result),
        "total_tokens": extract_total_tokens(result),
        "error": extract_error_message(result),
    }


def extract_model(result: BatchResultLine) -> str | None:
    if not result.body:
        return None
    return result.body.get("model")


def collect_contents(results: list[BatchResultLine]) -> dict[str, str]:
    """custom_id -> content for every successful result line."""

    out: dict[str, str] = {}
    for result in results:
        content = extract_message_content(result)
        if content is not None:
            out[result.custom_id] = content
    return out


def build_success_body(content: str, total_tokens: int = 0) -> dict:
    """Construct a chat-completion body for fixtures and round-tripping."""

    return {
        "id": "chatcmpl-fixture",
        "object": "chat.completion",
        "choices": [
            {
                "index": 0,
                "message": {"role": "assistant", "content": content},
                "finish_reason": "stop",
            }
        ],
        "usage": {"total_tokens": total_tokens},
    }

