from __future__ import annotations

"""Tie each batch result back to the request that produced it."""

from batch_models import BatchRequestLine, BatchResultLine


def match_results(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> dict[str, BatchResultLine | None]:
    """Return a mapping of request custom_id -> its result line (or None).

    Results arrive in the order the batch finished them. We line them up with
    the requests we sent and pair them off, leaving anything unpaired as None.
    """

    usable = [r for r in results if r.is_success()]

    matched: dict[str, BatchResultLine | None] = {}
    for request, result in zip(requests, usable):
        matched[request.custom_id] = result

    for request in requests:
        matched.setdefault(request.custom_id, None)

    return matched


def unmatched_result_ids(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> list[str]:
    """custom_ids present in the output that were not in the request set."""

    request_ids = {r.custom_id for r in requests}
    return [r.custom_id for r in results if r.custom_id not in request_ids]


def duplicate_result_ids(results: list[BatchResultLine]) -> list[str]:
    seen: set[str] = set()
    dupes: set[str] = set()
    for result in results:
        if result.custom_id in seen:
            dupes.add(result.custom_id)
        seen.add(result.custom_id)
    return sorted(dupes)


def answered_request_ids(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> list[str]:
    """Request custom_ids that ended up with some result line attached."""

    matched = match_results(requests, results)
    return [cid for cid, result in matched.items() if result is not None]


def coverage(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> dict[str, int]:
    answered = answered_request_ids(requests, results)
    return {
        "requested": len(requests),
        "returned": len(results),
        "answered": len(answered),
        "unanswered": len(requests) - len(answered),
    }


def unanswered_request_ids(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> list[str]:
    matched = match_results(requests, results)
    return [cid for cid, result in matched.items() if result is None]


def all_ids_present(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> bool:
    """True when every request received some result line."""

    return not unanswered_request_ids(requests, results)

