def answered_request_ids(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> list[str]:
    """Request custom_ids that ended up with some result line attached."""

    matched = match_results(requests, results)
    return [cid for cid, result in matched.items() if result is not None]


def coverage(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> dict[str, int]:
    answered = answered_request_ids(requests, results)
    return {
        "requested": len(requests),
        "returned": len(results),
        "answered": len(answered),
        "unanswered": len(requests) - len(answered),
    }


def unanswered_request_ids(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> list[str]:
    matched = match_results(requests, results)
    return [cid for cid, result in matched.items() if result is None]


def all_ids_present(
    requests: list[BatchRequestLine],
    results: list[BatchResultLine],
) -> bool:
    """True when every request received some result line."""

    return not unanswered_request_ids(requests, results)
